      "cardLead": "新石器时代贴塑壁虎纹罐出土于铜川王家河乡前峁，以泥条贴塑壁虎于罐腹。",
      "essay": [
        {
          "heading": "历史",
          "text": "新石器时代。铜川市王家河乡前峁出土。贴塑动物纹饰在仰韶文化陶器中较为少见，这件器物以立体壁虎装饰罐腹，手法独特。"
        },
        {
          "heading": "形制与工艺",
          "text": "泥质陶。壁虎以泥条和泥片贴附于罐腹，再与器身一同烧成，属贴塑而非平面彩绘。 隆起的四肢、躯干和尾部顺着曲面展开，贴塑边缘与罐体接合处可直接显示装饰如何依附在日用容器上。"
        },
        {
          "heading": "地位与价值",
          "text": "贴塑壁虎纹是研究新石器陶器立体装饰技法的罕见例证，反映当时对动物形态的观察与再现能力。 壁虎以立体贴塑进入罐体，不同于彩陶上以笔绘成的动物纹。 动物形象与储藏容器结合，可能涉及护佑、环境经验或群体识别，但现有展签不足以确定单一解释； 出土单位、同类纹样和使用残留是继续讨论的依据。"
        },
        {
          "heading": "观看指引",
          "text": "摸不到——但可用眼细看：壁虎是凸起于器表的立体附件，不是画上去的平面纹饰。 壁虎不是画上去的，而是以泥条和泥片贴附在罐腹，再与器身一同烧成。 隆起的四肢、躯干和尾部顺着曲面展开，贴塑边缘与罐体接合处可直接显示装饰如何依附在日用容器上。"
        }
      ],
      "evidence": "器物图为 DSC_3909—DSC_3910；名称、时代与来源由相邻展签核对，展签画面不作为器物封面。原始照片保存在 F:\\DCIM\\102NCZ_F。",
