      "essay": [
        {
          "heading": "历史",
          "text": "新石器时代。西安市临潼区姜寨遗址出土。姜寨是仰韶文化半坡类型的重要聚落遗址，与半坡遗址同期。人面鱼纹是半坡类型的标志性纹饰，以人面与鱼的组合为特征。"
        },
        {
          "heading": "形制与工艺",
          "text": "泥质红陶。彩绘集中在盆内，人面与鱼纹沿内壁组合，黑色线面随圆形器壁展开。 人物五官、鱼体与几何分区的关系比单个母题更重要； 盆的盛放功能和图像在使用、埋藏中的可见程度，需要结合出土位置判断。"
        },
        {
          "heading": "地位与价值",
          "text": "人面鱼纹是仰韶文化半坡类型最著名的纹饰主题，其含义在学术界有多种解释（图腾、巫术、捕鱼场景等），是研究新石器精神世界的重要材料。 姜寨遗址的人面鱼纹材料与半坡文化彩陶传统相关，但同题材器物在出土地点、构图和使用痕迹上并不完全相同。 人面、鱼和圆形盆体如何组合，可用于讨论仰韶时期图像传统； 至于祭祀、葬具或日用等用途，必须分别看考古情境。"
        },
        {
          "heading": "观看指引",
          "text": "看人面与鱼的位置关系——人面嘴角两侧各衔一鱼（或以鱼形为耳饰），这一组合是半坡人面鱼纹的核心构图。 彩绘集中在盆内，人面与鱼纹沿内壁组合，黑色线面随圆形器壁展开。 人物五官、鱼体与几何分区的关系比单个母题更重要；"
        }
      ],
