      "summary": "新石器时代 · 陶器 · 西安市临潼区姜寨遗址出土",
      "cardLead": "新石器时代白陶鬶出土于临潼姜寨遗址，以三袋足支撑，一侧设流一侧设鋬。",
      "essay": [
        {
          "heading": "历史",
          "text": "新石器时代。西安市临潼区姜寨遗址出土。鬶是用于温注液体的陶器，在仰韶及大汶口文化中均有出现，白陶鬶以高岭土为原料，烧成后呈白色或灰白色。"
        },
        {
          "heading": "形制与工艺",
          "text": "白陶（高岭土质）。三只袋状足支撑腹腔，一侧伸出流，另一侧设鋬，兼顾加热、提持和倾注。 白陶胎色、薄壁和复杂中空结构要求各部件在干燥与烧成时保持平衡，任何接合处开裂都会破坏整器。"
        },
        {
          "heading": "地位与价值",
          "text": "白陶鬶反映了仰韶时期对高岭土的使用和袋足器的成型工艺，是研究新石器陶器形制演变与功能设计的材料。 史前聚落中的食物处理、储藏、工具制作和仪式活动，常以耐久材料留存。 出土地点与地层关系决定器物年代，也使不同遗址的技术传播可以比较。 白陶鬶保留的轮廓、连接方式和使用痕迹，可以与同类器、墓葬组合和文字资料核对，由此缩小对实际功能的判断范围。"
        },
        {
          "heading": "观看指引",
          "text": "看三个袋足与流的连接——袋足空心便于受热，流与鋬的方位决定倾注方向。 鬶以三只袋状足支撑腹腔，一侧伸出流，另一侧设鋬，兼顾加热、提持和倾注。 白陶胎色、薄壁和复杂中空结构要求各部件在干燥与烧成时保持平衡，任何接合处开裂都会破坏整器。"
        }
      ],
