      "cardLead": "新石器时代玉刀出土于神木石峁遗址，以玉料切割钻孔磨制而成，属龙山晚期礼器。",
      "essay": [
        {
          "heading": "历史",
          "text": "新石器时代。榆林市神木县石峁遗址出土。石峁是陕北龙山晚期至夏早期的大型石筑城址，玉器出土丰富，玉刀、玉璋等是其中的礼仪性器物。"
        },
        {
          "heading": "形制与工艺",
          "text": "玉质。以切割、钻孔、磨治和抛光成型，器身扁平，刃部磨制，多有钻孔用于固定或悬挂。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工； 天然色带、绺裂和表面磨痕也应与器形一起观察，而不能只以颜色判断品质。"
        },
        {
          "heading": "地位与价值",
          "text": "石峁玉刀是研究陕北龙山晚期玉器工艺与礼仪制度的重要材料，其形制与二里头等中原玉器存在关联，是探讨早期文明交流的物证。 石峁遗址的玉器与大型石构建筑、祭祀遗存共同出现。 玉刀保留刀形，却使用加工成本很高的玉料； 刃部、穿孔和磨光情况可以检验它是否承担切割、佩挂或礼仪陈设等功能。 它说明史前工具形制已经能够脱离单纯实用，进入身份与仪式表达。"
        },
        {
          "heading": "观看指引",
          "text": "看钻孔与刃部——钻孔用于固定，刃部的磨制痕迹反映玉工工艺。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工；"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_3942 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_3941，现场原片保存在 F:\\DCIM\\102NCZ_F。",
