      "cardLead": "商代兽面纹四足鬲出土于城固龙头镇龙头村，属城固铜器群，器表饰兽面纹。",
      "essay": [
        {
          "heading": "历史",
          "text": "商。汉中市城固县龙头镇龙头村出土。城固铜器群是商代晚期方国青铜器遗存，1950年以来城固、洋县湑水河两岸出土青铜器700余件，学界命名\"宝山文化\"，其族属可能与早期蜀文化或巴文化相关。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。鬲以袋状腹分成三足（此件以四足为变体），火焰可进入足间加热。器表饰兽面纹，分裆与足部受火痕迹是判断功能的重要部位。 纹饰分区与器形转折同步铸成； 若保存铭文，作器者、受命事件或宗族称谓还会把这件器物接入具体历史。"
        },
        {
          "heading": "地位与价值",
          "text": "城固铜器群是研究商代中原文化与汉水上游地方文化交融的关键材料，其礼器形制与殷墟相近，兵器（如三角援戈）具地方特征。 商周至战国的器物制度联系祖先祭祀、宴飨、战争和政治身份。 器类组合、尺寸等级、纹饰及铭文共同说明器物在礼制中的位置。 兽面纹四足鬲须与同墓或同窖藏的器类组合比较； 单件造型只能说明局部，成组关系才涉及宴飨程序、身份等级和器物制度。"
        },
        {
          "heading": "观看指引",
          "text": "看足部数量——四足鬲在商代铜鬲中为变体，与常见三足鬲不同；再看腹面兽面纹的布局。 袋状腹分成三足，火焰可进入足间加热，分裆、联裆和足部受火痕迹是判断功能的重要部位。 纹饰分区与器形转折同步铸成；"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_3946 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_3944—DSC_3945，现场原片保存在 F:\\DCIM\\102NCZ_F。",
