      "cardLead": "西周五祀钟出土于扶风庄白村窖藏，铭文记周王五祀事，属微氏家族青铜器。",
      "essay": [
        {
          "heading": "历史",
          "text": "西周。宝鸡市扶风县庄白村窖藏出土。1976年庄白村发现微氏家族青铜器窖藏103件，五祀钟是其中之一，铭文记周王五祀事。 与音乐的关系就在器物本身：它既能发声，也依靠尺寸、壁厚、悬挂和组合方式进入礼乐实践。 单件乐器说明音色与制作，成组出土还可讨论音列、编悬秩序和礼仪等级。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。甬钟，钟体饰枚与篆，钲部铸铭文，铭文记五祀事。 中空腔体、口沿与悬挂部位共同参与发声。 观察重点包括器壁厚薄、枚与篆带等表面分区，以及敲击位置和悬置方式； 这些形制既服务于声音，也把乐器纳入礼仪陈设的视觉秩序。"
        },
        {
          "heading": "地位与价值",
          "text": "五祀钟是研究西周钟铭与礼乐制度的重要材料，庄白窖藏微氏家族铜器群是西周铜器研究中最重要的考古发现之一。 保存了声音制度的物质条件。 器体尺寸、悬挂方式、敲击位置及同组乐器的排列关系，可用于讨论音高、音列和礼仪等级； 铭文若保存完整，还能把乐器与作器者及具体事件联系起来。"
        },
        {
          "heading": "观看指引",
          "text": "看钲部铭文——这是钟的定名由来；再看钟体枚与篆的排列方式。 中空腔体、口沿与悬挂部位共同参与发声。 观察重点包括器壁厚薄、枚与篆带等表面分区，以及敲击位置和悬置方式；"
        }
      ],
