          "text": "铜质。长颈鼓腹，盖与器口扣合，肩设提环，腹饰纹饰。 口、颈、肩、腹、盖与提携构件围绕贮存和倾注液体组织，器身转折也是纹饰与铭文的主要分界。 纹饰分区与器形转折同步铸成； 若保存铭文，作器者、受命事件或宗族称谓还会把这件器物接入具体历史。"
