          "text": "伯壶是研究西周丰镐地区贵族用器制度与铜器铭文的材料。 商周至战国的器物制度联系祖先祭祀、宴飨、战争和政治身份。 器类组合、尺寸等级、纹饰及铭文共同说明器物在礼制中的位置。 这类器物的关键动作是倾注。 口沿缺口、腹内残留、底足磨损和出土位置若能彼此印证，才可区分宴饮、储藏、供奉或随葬； 名称本身不能替代用途判断。"
