          "text": "伯百父鎣是研究西周中期丰镐贵族铜器形制与铭文的材料。 商周至战国的器物制度联系祖先祭祀、宴飨、战争和政治身份。 器类组合、尺寸等级、纹饰及铭文共同说明器物在礼制中的位置。 伯百父鎣保留的轮廓、连接方式和使用痕迹，可以与同类器、墓葬组合和文字资料核对，由此缩小对实际功能的判断范围。"
