      "summary": "西周 · 铜器 · 宝鸡市陈仓区西高泉村出土",
      "cardLead": "西周琱生豆出土于宝鸡陈仓西高泉村，铭文记琱生作器，属周原铜器群。",
      "essay": [
        {
          "heading": "历史",
          "text": "西周。宝鸡市陈仓区西高泉村出土。琱生是西周晚期贵族，琱生器在宝鸡地区出土多件。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。豆以盘、柄、圈足构成盛食与承托结构，盘内或器身铸铭文。 豆原本用于盛放食物，在礼仪组合中有明确位置； 器物以浅盘承接食物，下接粗长柄与外撇圈足，盘腹两侧的突起和器身转折使上部重量获得稳定支撑。 器内铭文说明琱生制作此豆，并将其用于宗室祭享； 文字没有脱离器物功能，而是把一次作器行为固定在礼器内部。"
        },
        {
          "heading": "地位与价值",
          "text": "琱生器群是研究西周晚期贵族铜器与土地制度的材料（琱生簋铭文涉及土地纠纷）。 西周有铭青铜器的价值在于器形、文字和出土地点可以互相校验。 琱生豆使宗族祭祀不再只是文献中的抽象制度：盛食之器如何制造、由谁作器、在何种空间使用，都能从同一件实物获得线索，也是观察周秦之际关中礼制传统的重要材料。"
        },
        {
          "heading": "观看指引",
          "text": "看盘与柄的比例——豆的盛食部分在盘内，柄的高度决定使用姿态。 豆原本用于盛放食物，在礼仪组合中有明确位置； 器物以浅盘承接食物，下接粗长柄与外撇圈足，盘腹两侧的突起和器身转折使上部重量获得稳定支撑。"
        }
      ],
