      "essay": [
        {
          "heading": "历史",
          "text": "西周。宝鸡市眉县李家村出土。方尊是西周盛酒礼器，有盖方尊较为少见。 尊主要用于盛酒，方形器在西周礼器中往往比常见圆体需要更复杂的范铸与合范控制。 完整的盖、器身和出土地点使它可以与同墓或同地区的簋、盨、卣等器物比较，进而讨论关中西周贵族如何通过器类、数量和纹饰组织祭祀宴飨。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。方体，侈口，束颈，鼓腹，圈足，有盖，腹饰纹饰。 器体横截面近方形，上有盖，下承圈足； 方折的肩、腹与足部把圆范传统难以处理的转角变成主要视觉结构。 盖与器身相合，既保护所盛酒液，也使纹饰能够从顶部延续到四壁。"
        },
        {
          "heading": "地位与价值",
          "text": "盖方尊是研究西周盛酒礼器形制演变与眉县铜器群的材料。"
        },
        {
          "heading": "观看指引",
          "text": "看方体的轮廓与盖的设置——有盖方尊在尊类中较为少见。 器体横截面近方形，上有盖，下承圈足； 方折的肩、腹与足部把圆范传统难以处理的转角变成主要视觉结构。"
        }
      ],
