      "essay": [
        {
          "heading": "历史",
          "text": "西周。移交入藏。京叔为器主名，京叔器在陕西地区有出土记录。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。椭方体，盖与器身对称，四足，器内铸铭文。 横长腹、双耳、盖与圈足构成盛黍稷的食器，盖身倒置或扣合方式常与成组陈设有关。 纹饰分区与器形转折同步铸成； 若保存铭文，作器者、受命事件或宗族称谓还会把这件器物接入具体历史。"
        },
        {
          "heading": "地位与价值",
          "text": "京叔盨是研究西周盛食器形制与铭文的材料。 商周至战国的器物制度联系祖先祭祀、宴飨、战争和政治身份。 器类组合、尺寸等级、纹饰及铭文共同说明器物在礼制中的位置。 京叔盨须与同墓或同窖藏的器类组合比较； 单件造型只能说明局部，成组关系才涉及宴飨程序、身份等级和器物制度。"
        },
        {
          "heading": "观看指引",
          "text": "看椭方体的盖与器身，以及器内铭文。 横长腹、双耳、盖与圈足构成盛黍稷的食器，盖身倒置或扣合方式常与成组陈设有关。 纹饰分区与器形转折同步铸成；"
        }
      ],
