      "tags": [],
      "tagsText": "",
      "summary": "西周 · 铜器 · 宝鸡市扶风县齐家村出土",
      "cardLead": "西周日己觥出土于扶风齐家村，器盖兽形，铭文记日己作器，属周原铜器群。",
      "essay": [
        {
          "heading": "历史",
          "text": "西周。宝鸡市扶风县齐家村出土。与日己方尊、方彝同属日己器群，是周原齐家村窖藏的组成部分。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。觥以兽形盖与器身构成，前流后鋬，圈足或四足，腹饰兽面纹，器盖与器内铸铭文。 酒器轮廓常结合兽形盖、流与鋬，动物形象同时承担启闭、倾注和装饰功能。 纹饰分区与器形转折同步铸成； 若保存铭文，作器者、受命事件或宗族称谓还会把这件器物接入具体历史。"
        },
        {
          "heading": "地位与价值",
          "text": "日己觥是研究西周觥形铜器造型与日己器群组合的重要材料。 商周至战国的器物制度联系祖先祭祀、宴飨、战争和政治身份。 器类组合、尺寸等级、纹饰及铭文共同说明器物在礼制中的位置。 日己觥保留的轮廓、连接方式和使用痕迹，可以与同类器、墓葬组合和文字资料核对，由此缩小对实际功能的判断范围。"
        },
        {
          "heading": "观看指引",
          "text": "看兽形盖的整体轮廓——觥盖常铸成兽首形，是其最具辨识度的部分；再看器内铭文。 酒器轮廓常结合兽形盖、流与鋬，动物形象同时承担启闭、倾注和装饰功能。 纹饰分区与器形转折同步铸成；"
        }
      ],
