      "summary": "汉 · 铜器 · 西安市三桥出土",
      "cardLead": "汉代“上林”铜鉴出土于西安三桥，铭文记“上林”，属上林苑用器。",
      "essay": [
        {
          "heading": "历史",
          "text": "汉。西安市三桥出土。上林苑是秦汉皇家苑囿，铜鉴铭文“上林”表明其为上林苑用器。鉴是盛水或盛冰的大盆。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。大口，深腹，圈足或无足，腹部设铺首衔环或无，腹外壁铸铭文。 宽口深腹能够盛水，也可用于鉴容、濯洗或冰鉴； 器口、附耳与腹部铭文决定具体用途。 纹饰分区与器形转折同步铸成； 若保存铭文，作器者、受命事件或宗族称谓还会把这件器物接入具体历史。"
        },
        {
          "heading": "地位与价值",
          "text": "铭文“上林”为研究汉代上林苑器用制度提供了实物证据。 它兼具照容、佩系和图像传播功能。 镜背纹样与铭文会随时代更换，出土组合和使用磨损则说明它属于日常用具、礼物还是随葬品； 同类镜的分布也可追踪铸镜技术和纹样范本的流动。"
        },
        {
          "heading": "观看指引",
          "text": "看腹壁铭文——“上林”表明此器的所属机构。 宽口深腹能够盛水，也可用于鉴容、濯洗或冰鉴； 器口、附耳与腹部铭文决定具体用途。"
        }
      ],
