          "text": "看肩部铺首衔环——这是仿铜器的典型装饰。 口沿、腹壁、底足与附加构件保存了成型和使用信息。 泥料、轮制或手制痕迹、烧成气氛以及釉彩覆盖方式，共同决定器物的重量感和表面效果；"
