      "cardLead": "汉代四神规矩纹镜，镜背饰四神与规矩纹（TLV纹），属汉代铜镜经典。",
      "essay": [
        {
          "heading": "历史",
          "text": "汉。馆藏。规矩纹镜（又称TLV纹镜或博局镜）是汉代铜镜的重要类型，四神配规矩纹是其经典布局。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。圆形，钮座，镜背以规矩纹（TLV纹）分隔四方，饰四神与铭文。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“四神规矩纹”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        },
        {
          "heading": "地位与价值",
          "text": "四神规矩纹镜是研究汉代铜镜纹饰与四神信仰的材料，是汉代铜镜的代表作。 它兼具照容、佩系和图像传播功能。 镜背纹样与铭文会随时代更换，出土组合和使用磨损则说明它属于日常用具、礼物还是随葬品； 同类镜的分布也可追踪铸镜技术和纹样范本的流动。"
        },
        {
          "heading": "观看指引",
          "text": "看镜背的TLV纹与四神布局——规矩纹将镜背分为四方八位，四神分列其中。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“四神规矩纹”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        }
      ],
