      "tags": [],
      "tagsText": "",
      "summary": "汉 · 铜器 · 榆林市绥德县出土",
      "cardLead": "汉代彩绘车马纹铜镜出土于绥德，镜背彩绘车马出行，属汉代铜镜。",
      "essay": [
        {
          "heading": "历史",
          "text": "汉。榆林市绥德县出土。彩绘铜镜在汉代铜镜中较少见，车马出行是汉代艺术常见主题。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。圆形，钮座，镜背以彩绘表现车马出行场景。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“彩绘车马纹铜”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        },
        {
          "heading": "地位与价值",
          "text": "彩绘铜镜是研究汉代铜镜装饰技法与绘画传统的材料。 它兼具照容、佩系和图像传播功能。 镜背纹样与铭文会随时代更换，出土组合和使用磨损则说明它属于日常用具、礼物还是随葬品； 同类镜的分布也可追踪铸镜技术和纹样范本的流动。"
        },
        {
          "heading": "观看指引",
          "text": "看镜背的彩绘——车马纹以彩色描绘，不同于常见的铸纹铜镜。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“彩绘车马纹铜”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4214 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4213，现场原片保存在 F:\\DCIM\\102NCZ_F。",
