          "heading": "地位与价值",
          "text": "鎏金银瓜棱形沐缶是研究西汉铜器高级装饰工艺的材料。 秦汉魏晋时期的郡县制度、墓葬观念和跨区域交通，均在器物生产与随葬组合中留下痕迹。 标准化与地方工艺往往同时存在。 鎏金银瓜棱形铜沐缶保留的轮廓、连接方式和使用痕迹，可以与同类器、墓葬组合和文字资料核对，由此缩小对实际功能的判断范围。"
