          "text": "看马与匈奴的比例——马的高大与匈奴的挣扎形成视觉张力。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工；"
