      "essay": [
        {
          "heading": "历史",
          "text": "汉。1979年西安市汉城乡郭家村出土。胡人抱瓶俑反映汉与西域的往来，黄釉是汉代铅釉。 “胡人”是古代文献和博物馆题名中对西域、北方或中亚来者的概括称呼，不能据一件俑的面貌直接落实到单一族群。 抱瓶动作使人物与供奉、侍从或运输场景发生联系，也说明外来者形象已进入汉代关中墓葬的随葬体系； 它保存的是当时社会对异域人物的视觉塑造，而非现代意义上的民族肖像。"
        },
        {
          "heading": "形制与工艺",
          "text": "陶质，黄釉。俑身为胡人形象（深目高鼻），怀抱瓶，施黄釉。 人物双臂抱持长颈瓶，面部特征、发式、服装与持物共同构成身份线索； 黄釉覆盖在陶胎表面，衣褶与手臂仍依靠塑形的高低转折保持清楚。"
        },
        {
          "heading": "地位与价值",
          "text": "胡人抱瓶俑是研究汉代胡人形象与铅釉陶俑的材料，反映汉与西域的往来。"
        },
        {
          "heading": "观看指引",
          "text": "看胡人的面部特征——深目高鼻是辨识胡人形象的关键；再看怀抱的瓶。 人物双臂抱持长颈瓶，面部特征、发式、服装与持物共同构成身份线索； 黄釉覆盖在陶胎表面，衣褶与手臂仍依靠塑形的高低转折保持清楚。"
        }
      ],
