      "essay": [
        {
          "heading": "历史",
          "text": "北周。西安市窦寨村出土。北周佛教造像承北魏风格而有变化。 北周关中佛教造像处于北朝晚期风格转变之中，人物体量、衣纹处理与面部塑造逐渐走向更饱满的形态。 窦寨村出土信息使这尊造像不只是孤立的宗教雕塑，还能与长安周边寺院、造像活动及北周政治文化联系起来。"
        },
        {
          "heading": "形制与工艺",
          "text": "石质或铜质。佛立像或坐像，面相方圆，衣纹贴体，有背光或无。 佛像以正面端严的姿态组织头光、躯干、衣纹与台座，衣褶不只表现衣料，也通过纵横线条加强身体的稳定感； 残损部位和石材表面保留了埋藏、搬移及长期保存留下的痕迹。"
        },
        {
          "heading": "地位与价值",
          "text": "北周佛造像是研究北周佛教艺术与造像风格演变的材料。"
        },
        {
          "heading": "观看指引",
          "text": "看面相与衣纹——北周佛像面相方圆，是辨识其时代的特征。 佛像以正面端严的姿态组织头光、躯干、衣纹与台座，衣褶不只表现衣料，也通过纵横线条加强身体的稳定感； 残损部位和石材表面保留了埋藏、搬移及长期保存留下的痕迹。"
        }
      ],
