          "text": "壁画。仕女高髻，面容丰润，手持如意，衣纹以线条表现。 人物、建筑、仪仗和出行依照墓道或墓室的位置排列，在地下重新布置墓主人的居处、秩序与身份。 它以连续的动作、人马或建筑构件组织画面，线描、设色和人物姿态共同形成视觉节奏。 墓室壁画的观看不能只停在单幅图像：它还涉及墓道方向、墙面位置、礼制等级以及画面与墓葬结构之间的关系。"
