          "heading": "形制与工艺",
          "text": "银质。笼身与提梁构成，笼身镂空或编织，顶设提梁。 应结合金属薄厚、锤揲起伏、焊接接缝和錾刻纹样观看。 金银延展性强，工匠可以用较薄的材料制造饱满体积，再以局部镶嵌、鎏金或细密刻划组织光泽，使结构和装饰在同一表面上发生。"
