      "essay": [
        {
          "heading": "历史",
          "text": "唐。西安市东郊王家坟唐墓出土。钱柜是唐代明器，模拟储钱柜。"
        },
        {
          "heading": "形制与工艺",
          "text": "陶质三彩。柜形，以黄、绿、白三彩釉表现，顶设投币口。 仿照木柜塑成：长方形柜体架在四足之上，正面设门、锁扣和成组乳钉，顶面及边框分区施釉。 黄、绿、褐色釉没有铺满全器，露胎处与釉色边界清楚，可见陶胎拼接、模印附件和低温铅釉共同完成一件微缩家具。"
        },
        {
          "heading": "地位与价值",
          "text": "三彩钱柜是研究唐代明器与三彩工艺的材料。 钱柜是唐代家庭储藏钱物的家具，这件陶质模型则进入墓葬随葬系统。 门扇、锁扣、乳钉和柜足被缩小后仍清楚可辨，说明制作者关心的是家具结构和财富保管方式。 它补充了传世家具稀少造成的材料缺口，也留下唐人如何把日常生活搬入墓室的具体证据。"
        },
        {
          "heading": "观看指引",
          "text": "看柜形与投币口——这是模拟实用钱柜的明器。 仿照木柜塑成：长方形柜体架在四足之上，正面设门、锁扣和成组乳钉，顶面及边框分区施釉。 黄、绿、褐色釉没有铺满全器，露胎处与釉色边界清楚，可见陶胎拼接、模印附件和低温铅釉共同完成一件微缩家具。"
        }
      ],
