          "text": "看铜兽首铰链与玉环的连接——铰链使臂环可开合，是此器的技术核心。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工；"
