      "essay": [
        {
          "heading": "历史",
          "text": "唐。西安市东郊唐墓出土。镇用于压席，异兽形是唐代镇器变体。"
        },
        {
          "heading": "形制与工艺",
          "text": "汉白玉质。异兽形，以圆雕表现，身有刻花或无。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工； 天然色带、绺裂和表面磨痕也应与器形一起观察，而不能只以颜色判断品质。"
        },
        {
          "heading": "地位与价值",
          "text": "汉白玉镇是研究唐代玉镇与异兽造型的材料。 隋唐长安连接宫廷、市场、宗教场所和交通路线。 原料、器形与装饰技法的迁移，会在宴饮、出行、信仰和日常用具中留下具体变化。 异兽形汉白玉镇所用石材的来源、切磨耗时与使用磨痕，可帮助区分实用器、陈设品和身份用品； 天然纹理也会影响工匠安排器形。"
        },
        {
          "heading": "观看指引",
          "text": "看异兽的姿态——异兽形在唐代镇器中是变体。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工；"
        }
      ],
