      "essay": [
        {
          "heading": "历史",
          "text": "元。西安市安西王府遗址出土。安西王府是元代安西王忙哥刺的府邸，遗址出土铁板幻方。"
        },
        {
          "heading": "形制与工艺",
          "text": "铁质。方形板，刻阿拉伯数字与幻方图。 它以平整金属面保存文字、数字或格局。 “交钞”铜板关注反向刻字、版框与印刷磨损，幻方铁板则要核对数字排列及方向； 边缘、厚度和锈蚀能够说明它是印版、陈设还是随身用具。"
        },
        {
          "heading": "地位与价值",
          "text": "幻方铁板是研究元代数学与阿拉伯数字传入中国的材料，是早期数学交流的实物。 五代以后，窑业、金属加工、城市消费与长距离贸易改变了器物的生产和流通。 旧器形仍被沿用，但配方、烧造和使用场景不断调整。 幻方铁板保留的轮廓、连接方式和使用痕迹，可以与同类器、墓葬组合和文字资料核对，由此缩小对实际功能的判断范围。"
        },
        {
          "heading": "观看指引",
          "text": "看阿拉伯数字与幻方布局——六阶幻方是其特征。 它以平整金属面保存文字、数字或格局。 “交钞”铜板关注反向刻字、版框与印刷磨损，幻方铁板则要核对数字排列及方向；"
        }
      ],
