      "essay": [
        {
          "heading": "历史",
          "text": "清。征集。湖州薛氏是明清铸镜名家，薛镜是其代表产品。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。圆形，钮座，镜背铸“湖州薛氏”铭文与纹饰。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“湖州薛”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        },
        {
          "heading": "地位与价值",
          "text": "湖州薛镜是研究明清铸镜业与薛氏铸镜传统的材料。 它兼具照容、佩系和图像传播功能。 镜背纹样与铭文会随时代更换，出土组合和使用磨损则说明它属于日常用具、礼物还是随葬品； 同类镜的分布也可追踪铸镜技术和纹样范本的流动。"
        },
        {
          "heading": "观看指引",
          "text": "看铭文——“湖州薛氏”是此镜的定名由来。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“湖州薛”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        }
      ],
