      "essay": [
        {
          "heading": "历史",
          "text": "宋。西安市蓝田县吕氏家族墓出土。吕氏家族墓是北宋士大夫家族墓地，出土多件文具。铭文记政和元年（1111年）。"
        },
        {
          "heading": "形制与工艺",
          "text": "歙石。长方形或圆形，下设三足，砚面开墨池与砚堂，底或侧刻“政和元年”铭文。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工； 天然色带、绺裂和表面磨痕也应与器形一起观察，而不能只以颜色判断品质。"
        },
        {
          "heading": "地位与价值",
          "text": "纪年铭文为宋代歙砚断代提供标准，吕氏家族墓出土文具是研究北宋士大夫文房器用的材料。 五代以后，窑业、金属加工、城市消费与长距离贸易改变了器物的生产和流通。 旧器形仍被沿用，但配方、烧造和使用场景不断调整。 题名中的引号标出器表原有文字。 字词内容可以确认作器者、官署、年号或吉语，字形所在部位又说明文字是铸成、刻入还是后加； 这些问题比把铭文只当作器名更具体。"
        },
        {
          "heading": "观看指引",
          "text": "看砚石纹理与铭文——歙石有天然罗纹，铭文是断代依据。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工；"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4511 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4509—DSC_4510，现场原片保存在 F:\\DCIM\\102NCZ_F。",
