      "summary": "北宋 · 玉石器 · 展签来源未完整记录",
      "cardLead": "北宋钟山石窟，属宋代石窟造像。",
      "essay": [
        {
          "heading": "历史",
          "text": "北宋。钟山石窟位于陕西子长，是北宋石窟代表。"
        },
        {
          "heading": "形制与工艺",
          "text": "石质。石窟内雕佛像与菩萨，以浮雕与圆雕表现。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工； 天然色带、绺裂和表面磨痕也应与器形一起观察，而不能只以颜色判断品质。"
        },
        {
          "heading": "地位与价值",
          "text": "钟山石窟是研究北宋石窟造像与陕北佛教的材料。 五代以后，窑业、金属加工、城市消费与长距离贸易改变了器物的生产和流通。 旧器形仍被沿用，但配方、烧造和使用场景不断调整。 钟山石窟所用石材的来源、切磨耗时与使用磨痕，可帮助区分实用器、陈设品和身份用品； 天然纹理也会影响工匠安排器形。"
        },
        {
          "heading": "观看指引",
          "text": "看造像风格——北宋石窟造像承唐而有变化。 价值集中在选料、切割、钻孔、磨治和抛光形成的轮廓。 玉石质地坚硬，细微的弧度与孔道往往需要长时间加工；"
        }
      ],
      "evidence": "名称、时代与来源优先取自 DSC_4571 中与画面中心器物对应的展签；说明牌只用于文字提取，不作为文物图片展示。可见器物图为 DSC_4562—DSC_4570，现场原片保存在 F:\\DCIM\\102NCZ_F。",
