      "tags": [],
      "tagsText": "",
      "summary": "唐 · 玉石器 · 西安市何家村唐代窖藏出土",
      "cardLead": "唐代镀金白玉臂环出土于西安何家村窖藏，以白玉为环、镀金铰链连接，属何家村窖藏玉器。",
      "essay": [
        {
          "heading": "历史",
          "text": "唐。西安市何家村窖藏出土。与鎏金铜兽首铰链玉臂环类似，以白玉为环。 何家村窖藏集中保存了金银器、玉带和身体装饰品，臂环由此进入唐代贵族服饰与珍宝收储的具体语境。 它的意义不只在材料昂贵，还在于玉与镀金工艺如何共同塑造佩戴效果，并让身体装饰成为身份、财富与审美选择的可见部分。"
        },
        {
          "heading": "形制与工艺",
          "text": "玉质，镀金铰链。白玉环以镀金铰链连接，可开合。 现场照片记录成对陈列的环体，随后拍到题名墙； 该题名画面只承担文字证据的作用，网站卡片保留器物照片，不再把它与后面的莲瓣纹提梁银罐合并。 臂环以白玉环体为主体，外加镀金金属构件，玉石的温润光泽与金属的明亮表面形成清楚对照。 成对保存使直径、厚薄、接口和装饰位置能够彼此参照，也说明这不是从一件复合器上脱落的普通环形零件。"
        },
        {
          "heading": "地位与价值",
          "text": "镀金白玉臂环是研究唐代玉器与镀金工艺的材料。"
        },
        {
          "heading": "观看指引",
          "text": "看镀金铰链与白玉环的连接。 现场照片记录成对陈列的环体，随后拍到题名墙； 该题名画面只承担文字证据的作用，网站卡片保留器物照片，不再把它与后面的莲瓣纹提梁银罐合并。"
        }
      ],
