      "summary": "唐 · 金银器 · 西安市何家村唐代窖藏出土",
      "cardLead": "唐代莲瓣纹提梁银罐出土于西安何家村窖藏，设提梁，饰莲瓣纹，属何家村窖藏银器。",
      "essay": [
        {
          "heading": "历史",
          "text": "唐。西安市何家村窖藏出土。提梁罐是唐代银器常见器形。"
        },
        {
          "heading": "形制与工艺",
          "text": "银质。罐身设提梁，腹饰莲瓣纹，盖与器口扣合。 应结合金属薄厚、锤揲起伏、焊接接缝和錾刻纹样观看。 金银延展性强，工匠可以用较薄的材料制造饱满体积，再以局部镶嵌、鎏金或细密刻划组织光泽，使结构和装饰在同一表面上发生。"
        },
        {
          "heading": "地位与价值",
          "text": "莲瓣纹提梁银罐是研究唐代银器工艺与何家村窖藏的材料。 隋唐长安连接宫廷、市场、宗教场所和交通路线。 原料、器形与装饰技法的迁移，会在宴饮、出行、信仰和日常用具中留下具体变化。 这类器物的关键动作是盛放与取用。 口沿缺口、腹内残留、底足磨损和出土位置若能彼此印证，才可区分宴饮、储藏、供奉或随葬； 名称本身不能替代用途判断。"
        },
        {
          "heading": "观看指引",
          "text": "看提梁与莲瓣纹——提梁便于提携，莲瓣纹是唐代装饰。 应结合金属薄厚、锤揲起伏、焊接接缝和錾刻纹样观看。 金银延展性强，工匠可以用较薄的材料制造饱满体积，再以局部镶嵌、鎏金或细密刻划组织光泽，使结构和装饰在同一表面上发生。"
        }
      ],
