      "essay": [
        {
          "heading": "历史",
          "text": "唐。西安市何家村窖藏出土。赤金走龙是道教投龙致祭仪式用物，与玉璧、文简一同投入名山大川，奏告天地水三官。何家村窖藏出土12件赤金走龙。"
        },
        {
          "heading": "形制与工艺",
          "text": "金质。走龙形，四足行走，鳞、角以铸造表现，通体纯金。 它以细金条塑出长颈、拱背、四肢和上扬的尾部，体量很小，行走姿态却由关节转折清楚地建立起来。 头部、角、吻部与身上的刻划集中在有限表面内； 成组陈列时，各件朝向和步态略有差异，说明它们不是一件大型雕塑的零件，而是一组可以分别观看的微型金器。"
        },
        {
          "heading": "地位与价值",
          "text": "赤金走龙是研究唐代道教投龙仪式与金器工艺的重要材料，是唐代金银器中的罕见物品。 何家村窖藏中成组出现的微型金龙，把贵金属工艺、唐代仪式活动与窖藏主人的生活圈层联系在一起。 器物能够直接确认的是金质、成组、微型走兽形态及窖藏关系，具体用途仍需与出土组合和文献互证。 其价值正在于，一组极小的金器同时保存了高水平塑形能力与唐代信仰实践的线索。"
        },
        {
          "heading": "观看指引",
          "text": "看走龙的行走姿态——四足前行，是投龙仪式用物的典型造型；再看纯金质地。 它以细金条塑出长颈、拱背、四肢和上扬的尾部，体量很小，行走姿态却由关节转折清楚地建立起来。 头部、角、吻部与身上的刻划集中在有限表面内；"
        }
      ],
