      "summary": "唐 · 金银器 · 西安市何家村唐代窖藏出土",
      "cardLead": "唐代素面三足银铛出土于西安何家村窖藏，三足无纹，属何家村窖藏银器。",
      "essay": [
        {
          "heading": "历史",
          "text": "唐。西安市何家村窖藏出土。铛是温器，三足银铛是常见器形。"
        },
        {
          "heading": "形制与工艺",
          "text": "银质。浅腹，三足，单柄，无纹饰。 应结合金属薄厚、锤揲起伏、焊接接缝和錾刻纹样观看。 金银延展性强，工匠可以用较薄的材料制造饱满体积，再以局部镶嵌、鎏金或细密刻划组织光泽，使结构和装饰在同一表面上发生。"
        },
        {
          "heading": "地位与价值",
          "text": "素面银铛是研究唐代银铛形制与何家村窖藏的材料。 隋唐长安连接宫廷、市场、宗教场所和交通路线。 原料、器形与装饰技法的迁移，会在宴饮、出行、信仰和日常用具中留下具体变化。 素面三足银铛同时涉及贵金属来源、工匠技术和财富管理。 器表纹样及重量需与窖藏或墓葬组合对照，才能判断它用于宴饮、宗教供奉还是储备。"
        },
        {
          "heading": "观看指引",
          "text": "看三足与单柄——这是铛的功能结构。 应结合金属薄厚、锤揲起伏、焊接接缝和錾刻纹样观看。 金银延展性强，工匠可以用较薄的材料制造饱满体积，再以局部镶嵌、鎏金或细密刻划组织光泽，使结构和装饰在同一表面上发生。"
        }
      ],
