      "cardLead": "汉至晋乳鸟纹铜镜，1998年若羌罗布泊西岸采集，饰乳鸟纹，属汉至晋铜镜。",
      "essay": [
        {
          "heading": "历史",
          "text": "汉至晋。1998年新疆若羌县罗布泊西岸采集。乳鸟纹是铜镜纹饰。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质。圆形，钮座，镜背饰乳鸟纹。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“乳鸟纹铜”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        },
        {
          "heading": "地位与价值",
          "text": "乳鸟纹铜镜是研究汉至晋新疆铜镜与中原文化影响的材料。 它兼具照容、佩系和图像传播功能。 镜背纹样与铭文会随时代更换，出土组合和使用磨损则说明它属于日常用具、礼物还是随葬品； 同类镜的分布也可追踪铸镜技术和纹样范本的流动。"
        },
        {
          "heading": "观看指引",
          "text": "看乳鸟纹的布局——这是此镜的装饰特征。 照面经磨治用于映照，镜背则以钮、钮座和同心纹带组织“乳鸟纹铜”主题。 纹样并非附在功能之外：中央钮用于穿系，圆周分区顺应铸造表面，也让图像在转动镜体时依次展开。"
        }
      ],
