          "text": "清。1949年前陕西省历史博物馆移交。清代仿古铜钟以蟠螭纹为饰。 与音乐的关系就在器物本身：它既能发声，也依靠尺寸、壁厚、悬挂和组合方式进入礼乐实践。 单件乐器说明音色与制作，成组出土还可讨论音列、编悬秩序和礼仪等级。"
