          "text": "看内底双鱼与铭文——“君宜子孙”是汉代吉语。 敞口浅腹便于盛水和濯洗，双鱼等内底纹样要在水面变化或器内空置时才能完整显现。 纹饰分区与器形转折同步铸成；"
