      "cardLead": "宋代鎏金山水人物纹铜杯，饰山水人物，鎏金，属宋代铜器。",
      "essay": [
        {
          "heading": "历史",
          "text": "宋。鎏金铜杯以山水人物为饰，宋代铜器承唐而有变化。"
        },
        {
          "heading": "形制与工艺",
          "text": "铜质鎏金。杯形，以鎏金表现山水人物纹。 口沿、杯腹、附耳与底足围绕持握和饮用安排； 鎏金、刻铭或双耳又会改变观看重点。 纹饰分区与器形转折同步铸成； 若保存铭文，作器者、受命事件或宗族称谓还会把这件器物接入具体历史。"
        },
        {
          "heading": "地位与价值",
          "text": "鎏金铜杯是研究宋代铜器工艺与山水人物纹饰的材料。 五代以后，窑业、金属加工、城市消费与长距离贸易改变了器物的生产和流通。 旧器形仍被沿用，但配方、烧造和使用场景不断调整。 这类器物的关键动作是盛放与取用。 口沿缺口、腹内残留、底足磨损和出土位置若能彼此印证，才可区分宴饮、储藏、供奉或随葬； 名称本身不能替代用途判断。"
        },
        {
          "heading": "观看指引",
          "text": "看鎏金山水人物——山水人物是宋代铜器装饰主题。 口沿、杯腹、附耳与底足围绕持握和饮用安排； 鎏金、刻铭或双耳又会改变观看重点。"
        }
      ],
