          "text": "公元前150—前100年。出土于马其顿古城佩拉的众神之母圣所。阿纳迪奥梅涅式（Anadyomene）指阿佛洛狄忒从海中诞生的姿态。 它借阿佛洛狄忒及厄洛斯的形象讨论爱情、美、婚姻与生育。 神祇没有停留在神庙的大型雕像中，而是进入耳环、吊坠和随身小像； 佩戴者的身体由此成为神话图像发挥护佑、装饰和身份表达作用的场所。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
