          "text": "可能是陶或石质。半身像表现库柏勒佩戴珠宝的形象。 形制应结合轮廓、连接点、表面起伏和使用位置辨认。 器物经过锤揲、压模、金丝、焊接或镶嵌，成为可佩戴、可盛装或可供奉的具体结构； 光泽只是这些加工结果的一部分。"
