          "text": "公元前150—前125年。斯芬克斯是希腊神话中的狮身人面怪物。 它来自希腊化世界持续流动的图像与工艺网络。 王国、港口、商路和宗教仪式不断改写所谓“希腊风格”； 材料来源、制作方法与出土地点结合后，才能看出一件小型器物如何参与地中海与近东之间的交流。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
