          "heading": "观看指引",
          "text": "看潘神吹排箫与缪斯的组合——这是头带的装饰主题。 沿弧形带体展开，叶片、果实、花饰或人物附件依次固定在可环绕头部的结构上。 薄金片经过锤揲、压模和金丝连接形成轻巧体量，局部弯折与缺失也反映了这类首饰在佩戴、入葬及出土后的受力方式。"
