      "essay": [
        {
          "heading": "历史",
          "text": "希腊化时期。阿尔西诺伊二世是托勒密埃及的王后，八德拉克马是其纪念金币。 它兼具支付尺度与政治图像两种功能。 统治者或神祇肖像建立权力的可见面貌，铭文和重量体系保证货币能够跨地区识别； 磨损、窖藏和出土分布又记录了王国之间真实发生的交换。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
        },
        {
          "heading": "形制与工艺",
          "text": "金质。圆形，正面铸阿尔西诺伊二世像，背面铸双羊角与铭文。 它把正反两面的肖像、神祇、铭文和币制信息压缩在小型圆片上。 模铸造成的高低起伏必须兼顾辨识度与流通磨损； 边缘、轴向和残留重量，是判断铸造体系与使用经历的重要线索。"
        },
        {
          "heading": "地位与价值",
          "text": "此金币是研究希腊化埃及货币与阿尔西诺伊二世纪念币的材料。"
        },
        {
          "heading": "观看指引",
          "text": "看正面王后像与背面双羊角——双羊角象征丰饶。 它把正反两面的肖像、神祇、铭文和币制信息压缩在小型圆片上。 模铸造成的高低起伏必须兼顾辨识度与流通磨损；"
        }
      ],
