          "text": "公元前250—前200年。出土于马其顿安菲波利斯希腊化时期的一处墓葬。常春藤与酒神狄俄尼索斯相关。 它借常春藤、桃金娘、橄榄、橡树或果实等植物母题，把季节、生长、胜利与纪念转化为头部装饰。 此类金花冠往往脆薄，并不等同于日常首饰； 它与公共荣誉、宗教仪式及墓葬陈设之间的关系，使保存完整的部件具有特殊研究价值。 本次陈列见于“文明以止——希腊化时期的黄金艺术”特展。"
