      "tags": [
        "wall",
        "forbidden"
      ],
      "tagsText": "wall forbidden",
      "summary": "用户补入资料图 · 四幅未现场拍摄的壁画",
      "cardLead": "唐宫女图绘于永泰公主墓前室东壁南侧，绘九名宫女在女官引领下款款徐行，是唐墓壁画中女性形象最完美的一幅，禁止出境文物。",
      "essay": [
        {
          "heading": "历史",
          "text": "唐。乾县乾陵陪葬永泰公主墓出土。永泰公主李仙蕙是唐中宗之女，大足元年（701年）被武则天所杀，神龙二年（706年）陪葬乾陵。壁画绘于前室东壁南侧。 《宫女图》绘于唐永泰公主墓前室东壁南侧，1960 年发掘，现藏陕西历史博物馆； 画面约高 177 厘米、宽 198 厘米，并以一组列入第三批禁止出境展览文物目录。 馆方称其为永泰公主墓中保存最完整的女性群像之一。 九名宫女在女官引领下缓步前行，头梳不同高髻，肩披纱巾，长裙曳地。"
        },
        {
          "heading": "形制与工艺",
          "text": "壁画。前室东壁南侧，绘九名宫女，头梳高髻，肩披纱巾，长裙曳地，手捧方盒、酒杯、拂尘、如意、团扇、蜡烛等，在女官引领下徐行。"
        },
        {
          "heading": "地位与价值",
          "text": "宫女图是唐墓壁画中反映女性形象最完美的作品，被列入禁止出境展览文物目录，是研究唐代宫廷服饰与女性形象的重要壁画。"
        },
        {
          "heading": "观看指引",
          "text": "看九名宫女的姿态——或低语、或回顾、或凝神，是画面叙事核心；再看手持器物。"
        }
      ],
      "evidence": "此图为用户补入的资料图，不是本次现场拍摄；用于补齐未展出或未能现场拍摄的四件壁画条目。",
